from flask import Flask, render_template_string, request
from flask_socketio import SocketIO, emit
import eventlet
eventlet.monkey_patch()
app = Flask(__name__)
app.config['SECRET_KEY'] = 'codm_v3_hd_factory'
socketio = SocketIO(app, cors_allowed_origins='*', async_mode='eventlet')
PLAYERS = {}
HTML = """<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CODM V3 HD</title>
<style>*{margin:0;padding:0;box-sizing:border-box;font-family:sans-serif}html,body{width:100%;height:100%;overflow:hidden;background:#000;color:#fff}#c{width:100%;height:100%;position:absolute;top:0;left:0}#auth{position:absolute;width:100%;height:100%;background:#111;display:flex;justify-content:center;align-items:center;z-index:100}.card{background:#222;border:2px solid #ffcc00;padding:30px;border-radius:8px;width:350px;text-align:center}#hud{position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;display:none}.interactive{pointer-events:auto}#cross{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:20px;height:20px}#cross:before,#cross:after{content:'';position:absolute;background:#0f8}#cross:before{top:9px;left:0;width:20px;height:2px}#cross:after{top:0;left:9px;width:2px;height:20px}#weaponPanel{position:absolute;bottom:15px;right:15px;background:rgba(0,0,0,.8);padding:12px;border-right:3px solid #ffcc00}#action{position:absolute;top:58%;left:50%;transform:translate(-50%,-50%);background:#ffcc00;color:#000;padding:12px 24px;border-radius:20px;border:none;font-weight:900;display:none}#joy{position:absolute;bottom:25px;left:20px;width:120px;height:120px;background:rgba(255,255,255,.06);border-radius:50%;display:none}#knob{position:absolute;top:35px;left:35px;width:50px;height:50px;background:#ffcc00;border-radius:50%}#fireBtn{position:absolute;bottom:30px;right:20px;width:75px;height:75px;background:rgba(255,0,0,.6);border-radius:50%;display:none;align-items:center;justify-content:center;font-weight:900}#kill{position:absolute;top:100px;right:15px;width:220px;font-size:11px;text-align:right}.kf{background:rgba(0,0,0,.6);padding:4px 8px;margin-bottom:3px;border-right:2px solid red}
</style><script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/socket.io/4.7.2/socket.io.min.js"></script></head><body>
<div id="auth"><div class="card"><h1>CODM V3 HD</h1><p>Factory + Dragon AK</p><input id="name" placeholder="Operator"><button onclick="go()">DEPLOY</button></div></div>
<div id="c"></div><div id="hud"><div id="cross"></div><div id="weaponPanel"><div id="wt">AK-47 DRAGONFIRE</div><div id="ammo">30 / 120</div></div><div id="kill"></div><button id="action" class="interactive" onclick="jump()">JUMP (SPACE)</button><div id="joy" class="interactive"><div id="knob"></div></div><div id="fireBtn" class="interactive">FIRE</div><div style="position:absolute;top:10px;left:10px;background:rgba(0,0,0,.7);padding:8px;border-left:3px solid #ffcc00">OP: <span id="op">-</span> | <span id="st">IN PLANE</span></div></div>
<script>
let socket,scene,camera,renderer,player,plane,parachute,gun,flashLight,flashSprite,bots=[],others={},keys={},state='PLANE',weapon={ammo:30,max:30,reserve:120,dmg:36,rate:105},lastShot=0,kills=0;
function go(){let n=document.getElementById('name').value.trim();if(!n)return alert('Enter name');document.getElementById('op').innerText=n;document.getElementById('auth').style.display='none';document.getElementById('hud').style.display='block';init();initSocket();if('ontouchstart' in window){document.getElementById('joy').style.display='block';document.getElementById('fireBtn').style.display='flex';mobile();}}
function initSocket(){socket=io();socket.on('connect',()=>socket.emit('player_join',{username:document.getElementById('op').innerText}));socket.on('current_players',d=>{for(let id in d)if(id!==socket.id)makeOther(id,d[id]);});socket.on('player_joined',d=>makeOther(d.id,d));socket.on('player_moved',d=>{if(others[d.id])others[d.id].position.set(d.x,d.y,d.z);});socket.on('player_disconnected',id=>{if(others[id]){scene.remove(others[id]);delete others[id];}});}
function init(){scene=new THREE.Scene();scene.background=new THREE.Color(0x8aa0c8);scene.fog=new THREE.FogExp2(0x8aa0c8,0.008);camera=new THREE.PerspectiveCamera(75,innerWidth/innerHeight,0.1,1000);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;document.getElementById('c').appendChild(renderer.domElement);let loader=new THREE.TextureLoader();scene.add(new THREE.AmbientLight(0xffffff,0.6));let sun=new THREE.DirectionalLight(0xfff8e0,0.95);sun.position.set(120,250,80);sun.castShadow=true;scene.add(sun);let groundTex=loader.load('https://threejs.org/examples/textures/terrain/grasslight-big.jpg');groundTex.wrapS=groundTex.wrapT=THREE.RepeatWrapping;groundTex.repeat.set(25,25);let ground=new THREE.Mesh(new THREE.PlaneGeometry(800,800),new THREE.MeshStandardMaterial({map:groundTex,color:0xaaaaaa}));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);buildFactory(loader);makePlane();makePlayer();makeBots();addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='Space')jump();if(e.code==='KeyR')reload();});addEventListener('keyup',e=>keys[e.code]=false);addEventListener('mousedown',shoot);document.getElementById('action').style.display='block';anim();}
function buildFactory(loader){let crate=loader.load('https://threejs.org/examples/textures/crate.gif');for(let i=0;i<20;i++){let h=8+Math.random()*10,w=10+Math.random()*6,d=8+Math.random()*6;let b=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshStandardMaterial({map:crate}));let ang=(i/20)*Math.PI*2,dist=70+Math.random()*150;b.position.set(Math.cos(ang)*dist,h/2,Math.sin(ang)*dist);b.castShadow=true;scene.add(b);}for(let i=0;i<10;i++){let m=new THREE.Mesh(new THREE.CylinderGeometry(1.2,1.2,2,8),new THREE.MeshStandardMaterial({color:i%2?0x4444aa:0xaa4422}));m.position.set((Math.random()-0.5)*300,1,(Math.random()-0.5)*300);scene.add(m);}}
function makePlane(){plane=new THREE.Group();plane.add(new THREE.Mesh(new THREE.BoxGeometry(40,6,8),new THREE.MeshStandardMaterial({color:0x4a4a4a})));plane.position.set(-400,180,0);scene.add(plane);}
function makePlayer(){player=new THREE.Group();gun=new THREE.Group();let canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;let ctx=canvas.getContext('2d');let grad=ctx.createLinearGradient(0,0,256,256);grad.addColorStop(0,'#ff00ff');grad.addColorStop(0.3,'#00ffff');grad.addColorStop(0.6,'#ff9900');grad.addColorStop(1,'#4400ff');ctx.fillStyle=grad;ctx.fillRect(0,0,256,256);let dragonTex=new THREE.CanvasTexture(canvas);let rec=new THREE.Mesh(new THREE.BoxGeometry(0.28,0.38,1.7),new THREE.MeshStandardMaterial({map:dragonTex}));rec.position.set(0.38,-0.38,-0.95);let barrel=new THREE.Mesh(new THREE.BoxGeometry(0.09,0.09,1.3),new THREE.MeshStandardMaterial({color:0x111}));barrel.position.set(0.38,-0.3,-2.05);gun.add(rec,barrel);flashLight=new THREE.PointLight(0xffaa00,0,8);flashLight.position.set(0.38,-0.3,-2.7);gun.add(flashLight);let fc=document.createElement('canvas');fc.width=64;fc.height=64;let fctx=fc.getContext('2d');let fg=fctx.createRadialGradient(32,32,0,32,32,32);fg.addColorStop(0,'rgba(255,255,200,1)');fg.addColorStop(0.5,'rgba(255,80,0,0.6)');fg.addColorStop(1,'rgba(0,0,0,0)');fctx.fillStyle=fg;fctx.fillRect(0,0,64,64);let flashTex=new THREE.CanvasTexture(fc);let spriteMat=new THREE.SpriteMaterial({map:flashTex,blending:THREE.AdditiveBlending,transparent:true});flashSprite=new THREE.Sprite(spriteMat);flashSprite.position.set(0.38,-0.3,-2.8);flashSprite.scale.set(1.5,1.5,1);flashSprite.visible=false;gun.add(flashSprite);camera.add(gun);player.add(camera);player.position.set(-400,180,0);parachute=new THREE.Mesh(new THREE.ConeGeometry(5,3,8),new THREE.MeshBasicMaterial({color:0xeeeeee,wireframe:true}));parachute.position.y=5;parachute.visible=false;player.add(parachute);scene.add(player);}
function makeBots(){for(let i=0;i<10;i++){let g=new THREE.Group();let body=new THREE.Mesh(new THREE.BoxGeometry(0.9,1.5,0.5),new THREE.MeshStandardMaterial({color:0x2a3a2a}));let head=new THREE.Mesh(new THREE.BoxGeometry(0.45,0.45,0.45),new THREE.MeshStandardMaterial({color:0xd8b08c}));head.position.y=0.97;g.add(body,head);g.position.set((Math.random()-0.5)*350,0.75,(Math.random()-0.5)*350);g.userData={hp:100,dir:Math.random()*6};scene.add(g);bots.push(g);}}
function makeOther(id,data){let g=new THREE.Group();let b=new THREE.Mesh(new THREE.BoxGeometry(0.9,1.5,0.5),new THREE.MeshStandardMaterial({color:0x0066ff}));g.add(b);g.position.set(data.x||0,data.y||0.75,data.z||0);scene.add(g);others[id]=g;}
function jump(){if(state!=='PLANE')return;state='PARACHUTE';player.position.copy(plane.position);parachute.visible=true;document.getElementById('st').innerText='PARACHUTING';document.getElementById('action').style.display='none';}
function reload(){if(weapon.reserve<=0)return;let need=weapon.max-weapon.ammo;let take=Math.min(need,weapon.reserve);weapon.ammo+=take;weapon.reserve-=take;updAmmo();}
function updAmmo(){document.getElementById('ammo').innerHTML=weapon.ammo+' / '+weapon.reserve;}
function shoot(){if(state!=='GROUND')return;let now=Date.now();if(now-lastShot<weapon.rate||weapon.ammo<=0){if(weapon.ammo<=0)reload();return;}weapon.ammo--;lastShot=now;updAmmo();flashLight.intensity=8;flashSprite.visible=true;setTimeout(()=>{flashLight.intensity=0;flashSprite.visible=false;},70);let rc=new THREE.Raycaster();rc.setFromCamera(new THREE.Vector2(0,0),camera);let targets=[];bots.forEach(b=>{b.children.forEach(c=>targets.push(c));});let hits=rc.intersectObjects(targets,true);if(hits.length>0){let obj=hits[0].object;let root=obj;while(root.parent&&root.parent!==scene)root=root.parent;if(bots.includes(root)){root.userData.hp-=weapon.dmg;if(root.userData.hp<=0){root.position.set((Math.random()-0.5)*350,0.75,(Math.random()-0.5)*350);root.userData.hp=100;kills++;addKill('ELIMINATED '+kills);}}}}
function addKill(t){let k=document.getElementById('kill');let d=document.createElement('div');d.className='kf';d.innerText=t;k.prepend(d);setTimeout(()=>d.remove(),3000);}
function anim(){requestAnimationFrame(anim);if(state==='PLANE'){plane.position.x+=1.8;if(plane.position.x>400)plane.position.x=-400;player.position.copy(plane.position);camera.position.set(0,6,18);camera.lookAt(plane.position);}else if(state==='PARACHUTE'){player.position.y-=0.55;camera.position.set(0,9,22);if(player.position.y<=1){player.position.y=0.75;state='GROUND';parachute.visible=false;document.getElementById('st').innerText='COMBAT';}}else if(state==='GROUND'){let sp=keys['ShiftLeft']?0.7:0.38;if(keys['KeyW'])player.translateZ(-sp);if(keys['KeyS'])player.translateZ(sp);if(keys['KeyA'])player.translateX(-sp);if(keys['KeyD'])player.translateX(sp);player.position.y=0.75;bots.forEach(b=>{b.position.x+=Math.cos(b.userData.dir)*0.12;b.position.z+=Math.sin(b.userData.dir)*0.12;});if(socket)socket.emit('player_move',{x:player.position.x,y:player.position.y,z:player.position.z});}renderer.render(scene,camera);}
function mobile(){let zone=document.getElementById('joy'),knob=document.getElementById('knob'),fire=document.getElementById('fireBtn'),sx=0,sy=0,act=false;zone.addEventListener('touchstart',e=>{act=true;sx=e.touches[0].clientX;sy=e.touches[0].clientY;});zone.addEventListener('touchmove',e=>{if(!act)return;let dx=e.touches[0].clientX-sx,dy=e.touches[0].clientY-sy,d=Math.sqrt(dx*dx+dy*dy);if(d>45){dx=dx/d*45;dy=dy/d*45;}knob.style.transform='translate('+dx+'px,'+dy+'px)';let mx=dx/45,my=dy/45;if(state==='GROUND'){player.translateX(mx*0.55);player.translateZ(my*0.55);}e.preventDefault();},{passive:false});zone.addEventListener('touchend',()=>{act=false;knob.style.transform='translate(0,0)';});fire.addEventListener('touchstart',e=>{e.preventDefault();shoot();});}
</script></body></html>
"""
@app.route('/')
def home():
    return render_template_string(HTML)
@socketio.on('player_join')
def join(d):
    PLAYERS[request.sid] = {'username': d['username'], 'x': 0, 'y': 0.75, 'z': 0}
    emit('current_players', PLAYERS, to=request.sid)
    emit('player_joined', {'id': request.sid, **PLAYERS[request.sid]}, broadcast=True, include_self=False)
@socketio.on('player_move')
def move(d):
    if request.sid in PLAYERS:
        PLAYERS[request.sid].update(d)
        emit('player_moved', {'id': request.sid, **d}, broadcast=True, include_self=False)
@socketio.on('shoot_player')
def shoot(d):
    emit('player_shot_event', {'targetId': d.get('targetId'), 'damage': d.get('damage', 36)}, broadcast=True)
@socketio.on('disconnect')
def disc():
    PLAYERS.pop(request.sid, None)
    emit('player_disconnected', request.sid, broadcast=True)
if __name__ == '__main__':
    socketio.run(app, host='0.0.0.0', port=10000)
